class Solution:
    def search(self, nums: List[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:                      # closed interval [lo, hi]
            mid = (lo + hi) // 2
            if nums[mid] == target:
                return mid
            if nums[mid] < target:
                lo = mid + 1                 # target strictly right of mid
            else:
                hi = mid - 1                 # target strictly left of mid
        return -1

