class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        if not matrix or not matrix[0]:
            return False
        m, n = len(matrix), len(matrix[0])
        lo, hi = 0, m * n - 1                # virtual flat index range
        while lo <= hi:
            mid = (lo + hi) // 2
            r, c = divmod(mid, n)            # fold flat index back into grid
            v = matrix[r][c]
            if v == target:
                return True
            if v < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return False

