def brute_force(nums: List[int]) -> int:
    n = len(nums)
    dist = [-1] * n                          # BFS, enqueue every landing spot individually
    dist[0] = 0
    queue = [0]
    for i in queue:
        if i == n - 1:
            return dist[i]
        for j in range(i + 1, min(n, i + nums[i] + 1)):
            if dist[j] == -1:
                dist[j] = dist[i] + 1
                queue.append(j)
    return dist[n - 1]

def brute_force(gas: List[int], cost: List[int]) -> int:
    n = len(gas)
    for s in range(n):
        tank = 0
        for k in range(n):
            i = (s + k) % n
            tank += gas[i] - cost[i]
            if tank < 0:
                break
        else:
            return s
    return -1

