class Solution:
    def canCompleteCircuit(self, gas: List[int], cost: List[int]) -> int:
        total = tank = start = 0
        for i in range(len(gas)):
            diff = gas[i] - cost[i]
            total += diff
            tank += diff
            if tank < 0:                     # every start in [start, i] is doomed
                start, tank = i + 1, 0
        return start if total >= 0 else -1
